package com.yeyamo_mobile.api.moderation_trust_service.interfaces.rest;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.moderation_trust_service.application.ModerationService;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.*;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController@RequestMapping("/api/v1/moderation/reports")@Tag(name="Moderation reports")public class ModerationController{private final ModerationService service;public ModerationController(ModerationService s){service=s;}
 @PostMapping@ResponseStatus(HttpStatus.CREATED)@Operation(summary="Report content or an account",security=@SecurityRequirement(name="bearerAuth"))public ReportResponse create(@Valid@RequestBody ReportRequest r,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,Authentication auth){return ReportResponse.from(service.report(r.targetType(),r.targetId(),r.targetOwnerId(),auth.getName(),r.reason(),r.details(),correlation));}
 @GetMapping("/me")@Operation(summary="List my reports",security=@SecurityRequirement(name="bearerAuth"))public List<ReportResponse>mine(@RequestParam(defaultValue="50")@Min(1)@Max(200)int limit,Authentication auth){return service.list(null,auth.getName(),limit).stream().map(ReportResponse::from).toList();}
 @GetMapping@Operation(summary="Read moderation queue",security=@SecurityRequirement(name="bearerAuth"))public List<ReportResponse>list(@RequestParam(required=false)ReportStatus status,@RequestParam(defaultValue="100")@Min(1)@Max(200)int limit){return service.list(status,null,limit).stream().map(ReportResponse::from).toList();}
 @GetMapping("/{id}")public ReportResponse get(@PathVariable UUID id){return ReportResponse.from(service.get(id));}
 @PostMapping("/{id}/review")@Operation(summary="Assign a report and begin review",security=@SecurityRequirement(name="bearerAuth"))public ReportResponse review(@PathVariable UUID id,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,Authentication auth){return ReportResponse.from(service.review(id,auth.getName(),correlation));}
 @PostMapping("/{id}/decision")@Operation(summary="Approve or reject a report",security=@SecurityRequirement(name="bearerAuth"))public ReportResponse decide(@PathVariable UUID id,@Valid@RequestBody DecisionRequest r,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,Authentication auth){return ReportResponse.from(service.decide(id,r.status(),auth.getName(),r.resolution(),correlation));}}
